from decimal import Decimal
from fractions import Fraction
from typing import Any


def _numeric(value: Any) -> Fraction:
    """Apply legacy NVL numeric coercion without binary floating-point error."""
    if value is None or value == "":
        return Fraction(0)

    if isinstance(value, Fraction):
        return value
    if isinstance(value, Decimal):
        return Fraction(value)
    if isinstance(value, float):
        return Fraction(str(value))
    if isinstance(value, int):
        return Fraction(value)

    return Fraction(str(value))


def sweep(
    accounts: list[dict],
    orders: list[dict],
) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[Any, Any]] = []

    eligible_indices = [
        index
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG", "") != "Y"
        and account.get("ACCT_TYP") == "C"
    ]
    eligible_indices.sort(key=lambda index: accounts[index].get("ACCT_ID"))

    for index in eligible_indices:
        account = new_accounts[index]
        acct_id = account.get("ACCT_ID")

        exposure = Fraction(0)
        for order in orders:
            if (
                order.get("ACCT_ID") == acct_id
                and order.get("DEL_FLG", "") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _numeric(order.get("TOT_AMT", ""))

        credit_limit = _numeric(account.get("CRED_LIMIT", ""))

        if exposure > credit_limit and account.get("CRED_HOLD", "") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if (
            exposure <= credit_limit * Fraction(8, 10)
            and account.get("CRED_HOLD", "") == "Y"
        ):
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
